  const pic = { id: 'saeulen', labels: labs.map((f) => L(f[0], f[1])), values: vals, max: 15 };
  const i = randInt(rng, 0, k - 1), j = (i + 1 + randInt(rng, 0, k - 2)) % k;
  if (level === 1) return inputTask({ prompt: L(`Wie viele Kinder mögen am liebsten ${labs[i]![0]}?`, `Quanti bambini preferiscono ${labs[i]![1]}?`), pic, answer: vals[i]!, hint: L('Lies die Zahl über der Säule.', 'Leggi il numero sopra la colonna.'), explain: [String(vals[i])] });
