const ANGLE_NAMES = (deg: number) => (deg < 90 ? L('spitzer Winkel', 'angolo acuto') : deg === 90 ? L('rechter Winkel', 'angolo retto') : deg < 180 ? L('stumpfer Winkel', 'angolo ottuso') : deg === 180 ? L('gestreckter Winkel', 'angolo piatto') : L('überstumpfer Winkel', 'angolo concavo'));
const MS_WINKEL: PicGen[] = [
  gen((rng) => { const deg = pick(rng, [30, 45, 60, 90, 120, 135, 150, 180, 210, 270]); return choice({ prompt: L('Was für ein Winkel ist das?', 'Che tipo di angolo è?'), pic: { id: 'winkel', deg }, right: ANGLE_NAMES(deg), wrong: [20, 90, 120, 180, 240].map(ANGLE_NAMES), rng, hint: L('Vergleiche mit einem rechten Winkel (90°).', 'Confronta con un angolo retto (90°).'), explain: [`${deg}° → ${ANGLE_NAMES(deg)}`] }); }, 1),
  gen((rng) => { const deg = pick(rng, [30, 45, 60, 120, 135, 150]); return choice({ prompt: L('Wie groß ist der Winkel ungefähr?', 'Quanto misura circa l’angolo?'), pic: { id: 'winkel', deg }, right: `${deg}°`, wrong: [`${180 - deg}°`, `${deg + 30}°`, `${Math.max(10, deg - 30)}°`], rng, big: true, hint: L('Ein rechter Winkel hat 90°, ein halber 45°.', 'Un angolo retto misura 90°, la metà 45°.'), explain: [`${deg}°`] }); }, 2),
  gen((rng) => { const deg = pick(rng, [35, 50, 65, 110, 125, 140]); const neben = rng() < 0.5; return inputTask({ prompt: neben ? L(`Der Winkel ist ${deg}°. Wie groß ist sein Nebenwinkel (zusammen 180°)?`, `L’angolo misura ${deg}°. Quanto misura il suo supplementare (insieme 180°)?`) : L(`Der Winkel ist ${deg}°. Wie viel fehlt bis zum Vollwinkel (360°)?`, `L’angolo misura ${deg}°. Quanto manca all’angolo giro (360°)?`), pic: { id: 'winkel', deg, showDeg: true }, answer: (neben ? 180 : 360) - deg, hint: neben ? '180° − α' : '360° − α', explain: [`${neben ? 180 : 360}° − ${deg}° = ${(neben ? 180 : 360) - deg}°`] }); }, 3)
];
const MS_ABL: PicGen[] = [
  gen((rng) => { const m = pick(rng, [-2, -1, 1, 2, 3]), b = randInt(rng, -2, 2); return inputTask({ prompt: L('Die Gerade ist der Graph von f. Wie groß ist f′(x)?', 'La retta è il grafico di f. Quanto vale f′(x)?'), pic: { id: 'koordinaten', range: 5, line: { m, b } }, answer: m, signed: true, hint: L('Bei einer Geraden ist die Ableitung überall die Steigung.', 'Per una retta la derivata è la pendenza, ovunque uguale.'), explain: [lineEq(m, b), `f′(x) = ${m}`] }); }, 1),
  gen((rng) => { const h = randInt(rng, -3, 3), k = randInt(rng, -3, 1); return inputTask({ prompt: L('An welcher Stelle x ist f′(x) = 0?', 'In quale punto x vale f′(x) = 0?'), pic: { id: 'koordinaten', range: 5, parabola: { a: 1, b: -2 * h, c: h * h + k } }, answer: h, signed: true, hint: L('Am Scheitelpunkt ist die Tangente waagerecht.', 'Nel vertice la tangente è orizzontale.'), explain: [`x = ${h}`] }); }, 2),
  gen((rng) => { const a = randInt(rng, -2, 2) || 1; return inputTask({ prompt: L(`f(x) = x². Wie groß ist die Steigung im markierten Punkt (x = ${a})?`, `f(x) = x². Qual è la pendenza nel punto segnato (x = ${a})?`), pic: { id: 'koordinaten', range: 5, parabola: { a: 1, b: 0, c: 0 }, points: [{ x: a, y: a * a, label: 'P' }] }, answer: 2 * a, signed: true, hint: "f′(x) = 2x", explain: [`f′(${a}) = 2 × ${a} = ${2 * a}`] }); }, 3)
];

